def gen(rng):
    def fmt(ops):
        return str(len(ops)) + '\n' + '\n'.join(' '.join(map(str, o)) for o in ops)

    def rand_ops(q, maxx, pa, pb):
        ops, size = [], 0
        for _ in range(q):
            r = rng.random()
            if size > 0 and r < pa:
                ops.append((3,))
                size -= 1
            elif r < pa + pb:
                ops.append((2, rng.randint(1, maxx)))
            else:
                ops.append((1, rng.randint(1, maxx)))
                size += 1
        if not any(o[0] == 3 for o in ops):
            if size == 0:
                ops.append((1, rng.randint(1, maxx)))
            ops.append((3,))
        return ops

    tests = [
        fmt([(1, 3), (1, 5), (2, 10), (1, 12), (3,)]),
        fmt([(1, 1), (3,)]),
        fmt([(2, 5), (1, 1), (3,)]),
        fmt([(1, 7), (3,), (2, 4), (1, 2), (3,)]),
        fmt([(1, 10**9), (2, 10**9), (2, 10**9), (3,)]),
        fmt([(1, 5), (1, 5), (1, 5), (3,), (3,), (3,)]),
        fmt([(1, 1), (1, 2), (2, 100), (3,), (2, 1), (3,)]),
    ]
    for _ in range(14):
        tests.append(fmt(rand_ops(rng.randint(2, 28), rng.choice([5, 50, 10**9]), 0.3, 0.3)))
    for _ in range(6):
        tests.append(fmt(rand_ops(rng.randint(10, 28), 6, 0.45, 0.2)))
    tests.append(fmt(rand_ops(2000, 10**9, 0.3, 0.3)))
    tests.append(fmt(rand_ops(10**5, 10**9, 0.3, 0.3)))
    tests.append(fmt(rand_ops(10**5, 10, 0.4, 0.1)))
    tests.append(fmt([(1, rng.randint(1, 10**9)) for _ in range(50000)] + [(3,)] * 50000))
    ops = []
    for _ in range(33333):
        ops += [(2, 10**9), (1, rng.randint(1, 10**9)), (3,)]
    ops.append((1, 1))
    tests.append(fmt(ops))
    return tests

