    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int q = (int) in.nval;
        int[] types = new int[q];
        long[] values = new long[q];
        for (int i = 0; i < q; i++) {
            in.nextToken();
            types[i] = (int) in.nval;
            if (types[i] != 3) {
                in.nextToken();
                values[i] = (long) in.nval;
            }
        }
        long[] res = processQueries(types, values);
